def on_commit(self, func, robust=False):
    if not callable(func):
        raise TypeError("on_commit()'s callback must be a callable.")
    if self.in_atomic_block:
        # Transaction in progress; save for execution on commit.
        self.run_on_commit.append((set(self.savepoint_ids), func, robust))
    elif not self.get_autocommit():
        raise TransactionManagementError(
            "on_commit() cannot be used in manual transaction management"
        )
    else:
        # No transaction in progress and in autocommit mode; execute
        # immediately.
        if robust:
            try:
                func()
            except Exception as e:
                logger.error(
                    f"Error calling {func.__qualname__} in on_commit() (%s).",
                    e,
                    exc_info=True,
                )
        else:
            func()

def run_and_clear_commit_hooks(self):
    self.validate_no_atomic_block()
    current_run_on_commit = self.run_on_commit
    self.run_on_commit = []
    while current_run_on_commit:
        _, func, robust = current_run_on_commit.pop(0)
        if robust:
            try:
                func()
            except Exception as e:
                logger.error(
                    f"Error calling {func.__qualname__} in on_commit() during "
                    f"transaction (%s).",
                    e,
                    exc_info=True,
                )
        else:
            func()

@classmethod
@contextmanager
def captureOnCommitCallbacks(cls, *, using=DEFAULT_DB_ALIAS, execute=False):
    """Context manager to capture transaction.on_commit() callbacks."""
    callbacks = []
    start_count = len(connections[using].run_on_commit)
    try:
        yield callbacks
    finally:
        while True:
            callback_count = len(connections[using].run_on_commit)
            for _, callback, robust in connections[using].run_on_commit[
                start_count:
            ]:
                callbacks.append(callback)
                if execute:
                    if robust:
                        try:
                            callback()
                        except Exception as e:
                            logger.error(
                                f"Error calling {callback.__qualname__} in "
                                f"on_commit() (%s).",
                                e,
                                exc_info=True,
                            )
                    else:
                        callback()

            if callback_count == len(connections[using].run_on_commit):
                break
            start_count = callback_count

